mapper.sql:
WHERE 1 = 1

    AND EXISTS (
        SELECT 1 FROM org_class sc
        WHERE sc.class_code = t.classCode
          AND sc.status = 1
          AND sc.counselor_user_id = #{counselorId}
    )


    AND t.classCode = #{classCode}


    AND t.status = #{status}


    AND (t.studentName LIKE CONCAT('%', #{keyword}, '%')
         OR t.studentNo LIKE CONCAT('%', #{keyword}, '%'))
